1	package netdiag
2	
3	import (
4		"context"
5		"time"
6	
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/ports"
10	)
11	
12	// NewPortsDataMsg hands socket rows to the Ports view without reading the real
13	// socket table (guard seed, DEVDESK-150 H8).
14	func NewPortsDataMsg(sockets []ports.Socket) tea.Msg { return portsDataMsg{ports: sockets} }
15	
16	// defaultPortsRefresh is what the interval falls back to. A non-positive one —
17	// a hand-edited 0 in the config — would make tea.Tick fire without pausing and
18	// spin a docker exec per frame, so it is refused here rather than trusted.
19	const defaultPortsRefresh = 2 * time.Second
20	
21	func portsTickCmd(every time.Duration) tea.Cmd {
22		if every <= 0 {
23			every = defaultPortsRefresh
24		}
25		return tea.Tick(every, func(time.Time) tea.Msg {
26			return portsTickMsg{}
27		})
28	}
29	
30	// portsFetchTimeout bounds one read. Reverse DNS is the part that can hang —
31	// the socket table itself is a system call — and a fetch outliving several
32	// ticks would stack one behind another.
33	const portsFetchTimeout = 5 * time.Second
34	
35	func fetchPortsCmd(numeric bool) tea.Cmd {
36		return func() tea.Msg {
37			ctx, cancel := context.WithTimeout(context.Background(), portsFetchTimeout)
38			defer cancel()
39			sockets, err := ports.List(ctx, !numeric)
40			return portsDataMsg{ports: sockets, err: err}
41		}
42	}
43	
44	func killProcessCmd(pid string) tea.Cmd {
45		return func() tea.Msg {
46			return portsKillResultMsg{pid: pid, err: ports.Kill(pid)}
47		}
48	}
