18	// DEVDESK-717 (step 3 of DEVDESK-708): the confirmation of the Ports tab acts on
19	// the target it captured when it opened (S-01a criteria 5 and 6, bug
20	// DEVDESK-714), and says the truth on Windows (S-02a criteria 1 to 4).
21	//
22	// No test here reaches ports.Kill: every model installs a fake processOps whose
23	// kill only records the PID it was asked to signal.
24	
25	// fakeProcs records the PIDs the Ports tab asked to signal.
26	type fakeProcs struct {
27		killed []string
28		err    error
29	}
30	
31	func (f *fakeProcs) ops(windows bool) processOps {
32		return processOps{
33			kill: func(pid string) error {
34				f.killed = append(f.killed, pid)
35				return f.err
36			},
37			windows: windows,
38		}
39	}
40	
41	// installProcs puts a fresh recording fake on the model and returns it.
42	func installProcs(m *Model, windows bool) *fakeProcs {
43		f := &fakeProcs{}
44		m.portsModel.ops = f.ops(windows)
45		return f
46	}
47	
48	// sock is a LISTEN socket held by pid; the port follows the PID so rows differ.
49	func sock(pid, process string) ports.Socket {
50		return ports.Socket{
51			Protocol: "tcp", State: "LISTEN", LocalAddr: "0.0.0.0:" + pid, PeerAddr: "0.0.0.0:*",
52			PID: pid, Process: process,
53		}
54	}
55	
56	// nodeFirst and nodeLast are the same sockets in two orders: the refresh of the
57	// table reorders them while a confirmation is open (DEVDESK-714).
58	func nodeFirst() []ports.Socket {
59		return []ports.Socket{sock("4242", "node"), sock("812", "sshd"), sock("1204", "nginx")}
60	}
61	
62	func nodeLast() []ports.Socket {
63		return []ports.Socket{sock("812", "sshd"), sock("1204", "nginx"), sock("4242", "node")}
64	}
65	
66	// confirmOnNode returns a wide model whose cursor is on node (PID 4242) with
67	// the confirmation open, and the fake that records signals.
68	func confirmOnNode(t *testing.T) (*Model, *fakeProcs) {
69		t.Helper()
70		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
71		m = feed(t, m, portsDataMsg{ports: nodeFirst()})
72		m.portsModel.table.Table().SetCursor(0)
73		procs := installProcs(m, false)
74		if row, ok := m.portsModel.table.Selected(); !ok || row.PID != "4242" {
75			t.Fatalf("setup: selected row = %+v, want node (PID 4242)", row)
76		}
77		m = feed(t, m, testutil.Key(keymap.Kill))
78		if m.portsModel.confirmModal == nil {
79			t.Fatal("setup: K on node did not open the confirmation")
80		}
81		return m, procs
82	}
83	
84	// runKill executes the command a confirmed Yes returned. It must be the kill
85	// command itself, with no footer timer batched in (that would sleep 3 s).
86	func runKill(t *testing.T, cmd tea.Cmd) portsKillResultMsg {
87		t.Helper()
88		if cmd == nil {
89			t.Fatal("Yes returned no command")
90		}
91		res, ok := cmd().(portsKillResultMsg)
92		if !ok {
93			t.Fatalf("the command did not return a portsKillResultMsg")
94		}
95		return res
96	}
97	
98	// modalLines is the confirmation as rendered, border and padding removed, one
99	// entry per content line, stopping before the buttons.
100	func modalLines(m *Model) []string {
101		var out []string
102		for _, l := range strings.Split(ansi.Strip(m.portsModel.confirmModal.View()), "\n") {
103			l = strings.TrimSpace(strings.Trim(strings.TrimSpace(l), "│┌┐└┘─"))
104			if strings.Contains(l, "Yes") && strings.Contains(l, "No") {
105				break
106			}
107			out = append(out, l)
108		}
109		for len(out) > 0 && out[0] == "" {
110			out = out[1:]
111		}
112		for len(out) > 0 && out[len(out)-1] == "" {
113			out = out[:len(out)-1]
114		}
115		return out
116	}
117	
118	// modalTitle and modalBody split modalLines at the title's blank line.
119	func modalTitle(m *Model) string { return modalLines(m)[0] }
120	
121	func modalBody(m *Model) string {
122		return strings.TrimLeft(strings.Join(modalLines(m)[1:], "\n"), "\n")
123	}
124	
125	// squash folds every run of whitespace into one space.
126	func squash(s string) string { return strings.Join(strings.Fields(s), " ") }
