128	// ── S-01a criterion 5 and the DEVDESK-714 bug ────────────────────────────────
129	
130	func TestYesKillsTheCapturedTargetAfterTheTableReorders(t *testing.T) {
131		m, procs := confirmOnNode(t)
132	
133		// The refresh lands before the user answers. The cursor stays on index 0,
134		// which is now sshd: the pre-fix code killed that row.
135		m = feed(t, m, portsDataMsg{ports: nodeLast()})
136		if row, _ := m.portsModel.table.Selected(); row.PID != "812" {
137			t.Fatalf("setup: after the reorder the selected row is %+v, want sshd (PID 812)", row)
138		}
139	
140		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
141		res := runKill(t, cmd)
142	
143		if res.pid != "4242" {
144			t.Errorf("kill result pid = %q, want 4242", res.pid)
145		}
146		if len(procs.killed) != 1 || procs.killed[0] != "4242" {
147			t.Errorf("signalled PIDs = %v, want exactly [4242] (never the selected row, 812)", procs.killed)
148		}
149		if !m.portsModel.table.IsBusy("4242") {
150			t.Error("the captured target is not marked busy")
151		}
152		if m.portsModel.table.IsBusy("812") {
153			t.Error("the row under the cursor was marked busy: Yes read the selection")
154		}
155		if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
156			t.Error("the confirmation or its captured target survived Yes")
157		}
158	}
