160	// Rule 110: the command receives values, never the model. Whatever happens to
161	// the model between Yes and the moment the command runs, the signal goes to the
162	// PID captured in Update and through the function captured in Update.
163	func TestTheKillCommandCarriesValuesNotTheModel(t *testing.T) {
164		m, procs := confirmOnNode(t)
165		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
166	
167		m.portsModel.table.SetItems(nodeLast())
168		m.portsModel.table.Table().SetCursor(2)
169		m.portsModel.pendingKill = nil
170		m.portsModel.ops = processOps{kill: func(string) error {
171			panic("the command read the model's processOps after Update returned")
172		}}
173	
174		res := runKill(t, cmd)
175	
176		if res.pid != "4242" || len(procs.killed) != 1 || procs.killed[0] != "4242" {
177			t.Errorf("result pid = %q, signalled = %v, want 4242 through the function captured in Update", res.pid, procs.killed)
178		}
179	}
