193	// A confirmation is only ever answered by a message from the modal: a Yes that
194	// arrives with nothing open used to kill whatever the cursor stood on.
195	func TestAStrayYesKillsNothing(t *testing.T) {
196		m := portsModel(t)
197		procs := installProcs(m, false)
198		m.portsModel.table.Table().SetCursor(0) // sshd, PID 812
199	
200		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
