215	func TestTheConfirmationDoesNotFollowTheSelection(t *testing.T) {
216		for _, tt := range []struct {
217			name string
218			then []tea.Msg
219		}{
220			{"the selection moves", append(testutil.Keys("down", "down", "up"), portsDataMsg{ports: nodeLast()})},
221			{"the process disappears", []tea.Msg{portsDataMsg{ports: []ports.Socket{sock("812", "sshd"), sock("1204", "nginx")}}}},
222			{"the table empties", []tea.Msg{portsDataMsg{ports: nil}}},
