290	func TestYesOnAVanishedTargetSendsNothing(t *testing.T) {
291		for _, tt := range []struct {
292			name  string
293			table []ports.Socket
294		}{
295			{"the PID is gone", []ports.Socket{sock("812", "sshd"), sock("1204", "nginx")}},
296			{"the PID is back under another name", []ports.Socket{sock("4242", "python"), sock("812", "sshd")}},
297			{"the table is empty", nil},
298		} {
299			t.Run(tt.name, func(t *testing.T) {
300				m, procs := confirmOnNode(t)
301				m = feed(t, m, portsDataMsg{ports: tt.table})
302	
303				m, cmd := step(t, m, components.ConfirmModalYesMsg{})
304	
305				if len(procs.killed) != 0 {
306					t.Errorf("signalled %v for a target that is no longer listed", procs.killed)
307				}
308				if cmd == nil {
309					t.Error("no command returned, so the footer warning would never clear")
310				}
311				if got := m.portsModel.footer.Text(); got != goneWarning {
312					t.Errorf("footer = %q, want %q", got, goneWarning)
313				}
314				if got := m.portsModel.footer.Level(); got != components.LevelWarning {
315					t.Errorf("footer level = %v, want Warning (nothing failed, a precondition is unmet)", got)
316				}
317				if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
318					t.Error("the confirmation stayed open after Yes")
319				}
320				if m.portsModel.table.IsBusy("4242") {
321					t.Error("the vanished target was marked busy")
322				}
323			})
324		}
