364	// Rule 128 at 80 columns: the warning is one centred line, whole, and the
365	// footer keeps the height the router budgeted.
366	func TestTheVanishedTargetWarningFitsAt80Columns(t *testing.T) {
367		m, _ := confirmOnNode(t)
368		m = feed(t, m, tea.WindowSizeMsg{Width: 80, Height: 30})
