386	// ── S-02a: the wording per platform ──────────────────────────────────────────
387	
388	const (
389		windowsPrompt = "Terminate node.exe (PID 4412)? Windows has no clean stop for this process: it is ended at once and cannot save anything."
390		unixBody      = "Send SIGKILL to sshd (PID 812)?\n\nThe process gets no chance to shut down cleanly."
391		unixHelp      = "Send SIGKILL to the selected process, after confirmation (Ports tab)"
392		windowsHelp   = "End the selected process at once, after confirmation (Ports tab)"
