395	// windowsNode is a Windows model with the confirmation open on node.exe.
396	func windowsNode(t *testing.T) (*Model, *fakeProcs) {
397		t.Helper()
398		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
399		m = feed(t, m, portsDataMsg{ports: []ports.Socket{sock("4412", "node.exe"), sock("812", "sshd")}})
400		m.portsModel.table.Table().SetCursor(0)
401		procs := installProcs(m, true)
402		m = feed(t, m, testutil.Key(keymap.Kill))
403		if m.portsModel.confirmModal == nil {
404			t.Fatal("setup: K on node.exe did not open the confirmation")
405		}
406		return m, procs
