431	// S-02a criterion 2: one gesture, no wait, no second confirmation.
432	func TestWindowsStopIsOneGesture(t *testing.T) {
433		m, procs := windowsNode(t)
434	
435		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
436		if m.portsModel.confirmModal != nil {
