456	// S-02a criterion 3: nothing on Windows suggests a clean stop, and K stays
457	// "Kill".
458	func TestWindowsLabelsPromiseNoCleanStop(t *testing.T) {
459		m, _ := windowsNode(t)
460		body := modalBody(m) // read before Yes closes the confirmation
461	
462		labels := map[string]string{
463			"modal title": modalTitle(m),
464			"help":        helpFor(m),
465		}
466		for _, s := range m.GetShortcuts() {
467			if s.Key == keymap.Kill {
468				labels["shortcut"] = s.Description
469			}
470		}
471		busy := feed(t, m, components.ConfirmModalYesMsg{})
472		labels["busy label"], _ = busy.portsModel.table.BusyLabel("4412")
473		done := feed(t, busy, portsKillResultMsg{pid: "4412"})
474		labels["success"] = done.portsModel.footer.Text()
475	
476		want := map[string]string{
477			"modal title": "Kill Process",
478			"help":        windowsHelp,
479			"shortcut":    "Kill process",
480			"busy label":  "Killing node.exe (4412)",
481			"success":     "Process 4412 terminated",
482		}
483		for name, exp := range want {
484			if labels[name] != exp {
485				t.Errorf("%s = %q, want %q", name, labels[name], exp)
486			}
487		}
488	
489		forbidden := []string{"SIGTERM", "SIGKILL", "graceful", "Stop", "Ask", "clean"}
490		for name, got := range labels {
491			for _, bad := range forbidden {
492				if strings.Contains(got, bad) {
493					t.Errorf("%s = %q, which suggests a clean stop (%q)", name, got, bad)
494				}
495			}
496		}
497		for _, bad := range []string{"SIGTERM", "SIGKILL", "graceful", "Ask "} {
498			if strings.Contains(body, bad) {
499				t.Errorf("the Windows confirmation body mentions %q", bad)
500			}
501		}
502	}
