98	// modalLines is the confirmation as rendered, border and padding removed, one
99	// entry per content line, stopping before the buttons.
100	func modalLines(m *Model) []string {
101		var out []string
102		for _, l := range strings.Split(ansi.Strip(m.portsModel.confirmModal.View()), "\n") {
103			l = strings.TrimSpace(strings.Trim(strings.TrimSpace(l), "│┌┐└┘─"))
104			if strings.Contains(l, "Yes") && strings.Contains(l, "No") {
105				break
106			}
107			out = append(out, l)
108		}
109		for len(out) > 0 && out[0] == "" {
110			out = out[1:]
111		}
112		for len(out) > 0 && out[len(out)-1] == "" {
113			out = out[:len(out)-1]
114		}
115		return out
116	}
